/* === Metamorphic Cosmic Particle Cosmos (Procedural Uniqueness & Audio Shape-Shifting) === */
let particles = [];
let maxParticles = 260;
let cosmosDNA = {};
let lastSeedTime = 0;
let internalClock = 0;
let globalHueBase = 220;

function initCosmosDNA() {
  let families = ['SuperformulaSupershape', 'StellatedBioSpike', 'ElasticJellyBlob', 'QuantumResonanceOrb', 'CrystallinePrismFacet'];
  let physicsModes = ['CliffordStrangeAttractor', 'VortexViscousHydrodynamics', 'CoulombChargeLattice', 'KeplerCosmicOrbit'];

  let famIdx = Math.floor(random(families.length));
  let physIdx = Math.floor(random(physicsModes.length));

  cosmosDNA = {
    morphFamily: families[famIdx],
    physicsMode: physicsModes[physIdx],
    symmetryN: Math.floor(random(3, 9)),
    particleCount: Math.floor(random(180, 280)),
    viscosity: random(0.92, 0.975),
    elasticSquash: random(0.3, 0.8),
    spikeReach: random(1.8, 3.5),
    supershapeM: random(3, 8),
    supershapeN1: random(0.2, 1.5),
    supershapeN2: random(0.4, 2.0),
    supershapeN3: random(0.4, 2.0),
    attractorA: random(1.2, 2.6) * (random() > 0.5 ? 1 : -1),
    attractorB: random(1.0, 2.4) * (random() > 0.5 ? 1 : -1),
    attractorC: random(1.1, 2.2) * (random() > 0.5 ? 1 : -1),
    attractorD: random(0.8, 1.8) * (random() > 0.5 ? 1 : -1),
    chargeDispersion: random(0.8, 2.2),
    harmonicHueOffset: random(0, 360),
    pulseWaveSpeed: random(1.5, 4.0)
  };

  particles = [];
  let count = Math.min(cosmosDNA.particleCount, maxParticles);
  for (let i = 0; i < count; i++) {
    particles.push(new MetamorphicParticle(i, count));
  }
}

class MetamorphicParticle {
  constructor(id, total) {
    this.id = id;
    this.total = total;
    this.reset(true);
  }

  reset(initial = false) {
    let cx = width * 0.5;
    let cy = height * 0.5;
    let spread = min(width, height) * 0.38;
    let ang = random(TWO_PI);
    let dist = initial ? random(20, spread) : random(spread * 0.6, spread * 1.1);

    this.x = cx + cos(ang) * dist;
    this.y = cy + sin(ang) * dist;
    this.vx = random(-1.2, 1.2);
    this.vy = random(-1.2, 1.2);

    this.baseRadius = random(8, 28);
    this.currentRadius = this.baseRadius;
    this.charge = (this.id % 2 === 0 ? 1 : -1) * random(0.5, 1.5);
    this.mass = random(0.6, 2.4);
    this.phase = random(TWO_PI);
    this.rotSpeed = random(-0.04, 0.04);
    this.rotation = random(TWO_PI);
    this.life = 1.0;
    this.decay = random(0.0015, 0.0045);
    this.hueShift = random(-35, 35);
    this.vertexCount = cosmosDNA.symmetryN * 2 + (this.id % 3);
    this.vertexOffsets = [];
    for (let v = 0; v < this.vertexCount; v++) {
      this.vertexOffsets.push(random(0.7, 1.3));
    }
    this.squashFactor = 1.0;
    this.currentDeformM = cosmosDNA.supershapeM + (this.id % 4) * 0.5;
  }

  update(low, mid, high, beat, dt) {
    var cx = (typeof simulatedMouseX !== 'undefined' && simulatedMouseX !== null) ? simulatedMouseX : width * 0.5;
    var cy = (typeof simulatedMouseY !== 'undefined' && simulatedMouseY !== null) ? simulatedMouseY : height * 0.5;

    if (cosmosDNA.physicsMode === 'CliffordStrangeAttractor') {
      let scaleX = (this.x - width * 0.5) / (width * 0.28);
      let scaleY = (this.y - height * 0.5) / (height * 0.28);
      let targetVx = sin(cosmosDNA.attractorA * scaleY) + cosmosDNA.attractorC * cos(cosmosDNA.attractorA * scaleX);
      let targetVy = sin(cosmosDNA.attractorB * scaleX) + cosmosDNA.attractorD * cos(cosmosDNA.attractorB * scaleY);

      this.vx = lerp(this.vx, targetVx * (1.8 + low * 2.2), 0.12);
      this.vy = lerp(this.vy, targetVy * (1.8 + low * 2.2), 0.12);

    } else if (cosmosDNA.physicsMode === 'VortexViscousHydrodynamics') {
      let dx = this.x - cx;
      let dy = this.y - cy;
      let d = sqrt(dx * dx + dy * dy) + 1.0;
      let tangentX = -dy / d;
      let tangentY = dx / d;
      let vortexStrength = (3.5 + low * 5.0) / (1.0 + d * 0.0025);
      let radialPull = (d - min(width, height) * 0.32) * 0.004 * (1.0 + mid * 2.0);

      this.vx += tangentX * vortexStrength - (dx / d) * radialPull;
      this.vy += tangentY * vortexStrength - (dy / d) * radialPull;

    } else if (cosmosDNA.physicsMode === 'CoulombChargeLattice') {
      var dx = this.x - cx;
      var dy = this.y - cy;
      var d = sqrt(dx * dx + dy * dy) + 1.0;
      let centralForce = this.charge * (d - min(width, height) * 0.25) * 0.0035;

      this.vx += (-dx / d) * centralForce + sin(this.phase + internalClock * 2.0) * (0.8 + high * 2.0);
      this.vy += (-dy / d) * centralForce + cos(this.phase + internalClock * 2.0) * (0.8 + high * 2.0);

    } else {
      // Kepler Cosmic Orbit
      var dx = this.x - cx;
      var dy = this.y - cy;
      var d = sqrt(dx * dx + dy * dy) + 20.0;
      let gravity = (800.0 * (1.0 + low * 3.0)) / (d * d);
      let orbitTangentX = -dy / d * (2.8 + mid * 2.2);
      let orbitTangentY = dx / d * (2.8 + mid * 2.2);

      this.vx += - (dx / d) * gravity * 120.0 + orbitTangentX * 0.15;
      this.vy += - (dy / d) * gravity * 120.0 + orbitTangentY * 0.15;
    }

    this.vx *= cosmosDNA.viscosity;
    this.vy *= cosmosDNA.viscosity;

    let maxSpd = 14.0 + low * 18.0;
    let spd = sqrt(this.vx * this.vx + this.vy * this.vy);
    if (spd > maxSpd) {
      this.vx = (this.vx / spd) * maxSpd;
      this.vy = (this.vy / spd) * maxSpd;
    }

    this.x += this.vx;
    this.y += this.vy;
    this.rotation += this.rotSpeed * (1.0 + mid * 3.5);
    this.phase += 0.035 * (1.0 + high * 4.0);

    // Screen wrap / gentle bounce
    let margin = 60;
    if (this.x < -margin) this.x = width + margin;
    else if (this.x > width + margin) this.x = -margin;
    if (this.y < -margin) this.y = height + margin;
    else if (this.y > height + margin) this.y = -margin;

    // Audio-Driven Metamorphic Shape Dynamics
    let targetRadius = this.baseRadius * (1.0 + low * 1.8 + (beat ? 0.9 : 0.0));
    this.currentRadius = lerp(this.currentRadius, targetRadius, 0.22);

    // Squash & stretch (elastic volume conservation)
    let targetSquash = 1.0 + (spd / (maxSpd + 0.1)) * cosmosDNA.elasticSquash + low * 0.6;
    this.squashFactor = lerp(this.squashFactor, targetSquash, 0.18);
  }

  render(low, mid, high, beat, chordHue) {
    push();
    translate(this.x, this.y);
    rotate(this.rotation);

    let velAngle = atan2(this.vy, this.vx);
    rotate(velAngle * 0.35);

    // Scale with squash & stretch
    scale(this.squashFactor, 1.0 / max(0.2, this.squashFactor));

    let effectiveHue = (chordHue + cosmosDNA.harmonicHueOffset + this.hueShift + 360) % 360;
    let saturation = 75 + high * 25;
    let lightness = 50 + low * 35 + (beat ? 20 : 0);
    let alphaVal = 180 + high * 75;

    fill(effectiveHue, saturation, lightness, alphaVal);
    stroke((effectiveHue + 40) % 360, saturation * 0.9, lightness + 15, 230);
    strokeWeight(1.2 + high * 2.0);

    let fam = cosmosDNA.morphFamily;
    let r = this.currentRadius;

    beginShape();
    if (fam === 'SuperformulaSupershape') {
      // Superformula / Gielis supershape intra-particle deformation
      let m = this.currentDeformM + sin(internalClock + this.phase) * (1.0 + mid * 2.0);
      let n1 = cosmosDNA.supershapeN1 / (1.0 + low * 2.0);
      let n2 = cosmosDNA.supershapeN2 + mid * 1.5;
      let n3 = cosmosDNA.supershapeN3 + high * 1.5;
      let steps = 32;

      for (let i = 0; i < steps; i++) {
        let theta = (TWO_PI / steps) * i;
        let t1 = pow(abs(cos(m * theta / 4.0)), n2);
        let t2 = pow(abs(sin(m * theta / 4.0)), n3);
        let radMod = pow(t1 + t2, -1.0 / max(0.05, n1));
        if (!isFinite(radMod) || isNaN(radMod)) radMod = 1.0;
        radMod = constrain(radMod, 0.2, 4.0);

        let curR = r * radMod * (1.0 + 0.25 * sin(theta * cosmosDNA.symmetryN + internalClock * 5.0) * mid);
        vertex(cos(theta) * curR, sin(theta) * curR);
      }

    } else if (fam === 'StellatedBioSpike') {
      // Stellated Bio-Spike Organism
      let pts = this.vertexCount;
      let spikeExt = 1.0 + cosmosDNA.spikeReach * low + (beat ? 1.2 : 0.0);
      for (let i = 0; i < pts * 2; i++) {
        var theta = (TWO_PI / (pts * 2)) * i;
        let isSpike = (i % 2 === 0);
        let rad = isSpike ? r * spikeExt * this.vertexOffsets[i % pts] : r * 0.45;
        rad *= (1.0 + 0.2 * sin(theta * 3.0 + internalClock * 4.0) * mid);
        vertex(cos(theta) * rad, sin(theta) * rad);
      }

    } else if (fam === 'ElasticJellyBlob') {
      // Elastic Jelly Blob with multi-harmonic ripple
      var pts = 24;
      for (let i = 0; i < pts; i++) {
        var theta = (TWO_PI / pts) * i;
        let harmonicWave = sin(theta * cosmosDNA.symmetryN + internalClock * cosmosDNA.pulseWaveSpeed) * mid * 0.45;
        let microJitter = cos(theta * 8.0 + internalClock * 10.0) * high * 0.25;
        var curR = r * (1.0 + harmonicWave + microJitter);
        vertex(cos(theta) * curR, sin(theta) * curR);
      }

    } else if (fam === 'CrystallinePrismFacet') {
      // Crystalline Faceted Shard
      var pts = max(3, cosmosDNA.symmetryN);
      for (let i = 0; i < pts; i++) {
        var theta = (TWO_PI / pts) * i;
        let prismR = r * (i % 2 === 0 ? (1.3 + low * 0.8) : (0.7 - high * 0.3));
        vertex(cos(theta) * prismR, sin(theta) * prismR);
      }

    } else {
      // Quantum Resonance Orb with pulsing orbital rings
      var pts = 20;
      for (let i = 0; i < pts; i++) {
        var theta = (TWO_PI / pts) * i;
        let ringWobble = sin(theta * 4.0 + this.phase + internalClock * 6.0) * (0.2 + low * 0.4);
        var curR = r * (1.0 + ringWobble);
        vertex(cos(theta) * curR, sin(theta) * curR);
      }
    }
    endShape(CLOSE);

    // Inner luminous core that erupts on transients
    if (low > 0.45 || beat) {
      noStroke();
      fill((effectiveHue + 60) % 360, 95, 95, 200 + low * 55);
      let coreR = r * (0.25 + low * 0.35);
      ellipse(0, 0, coreR, coreR);
    }

    pop();
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 255);
  initCosmosDNA();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  let low = typeof audioLow !== 'undefined' ? audioLow : (typeof sub_bass !== 'undefined' ? sub_bass : 0.2);
  let mid = typeof audioMid !== 'undefined' ? audioMid : 0.2;
  let high = typeof audioHigh !== 'undefined' ? audioHigh : 0.2;
  let beat = typeof isBeat !== 'undefined' ? isBeat : false;
  let chord = typeof chordHue !== 'undefined' ? chordHue : globalHueBase;

  let now = millis() * 0.001;
  internalClock = now;

  // Periodic DNA mutation or section-triggered metamorphosis
  // 每隔 35-50 秒或大拍段落躍遷時，演化出全新不可重複的粒子系統拓撲！
  if (now - lastSeedTime > 42.0) {
    lastSeedTime = now;
    initCosmosDNA();
  }

  // Cosmic deep veil with dynamic persistence
  let bgAlpha = 22 + (1.0 - constrain(low, 0, 1)) * 30;
  background(230, 25, 8, bgAlpha);

  // Dynamic constellation filaments connecting nearest harmonic neighbours
  strokeWeight(0.8 + mid * 1.5);
  let linkThreshold = min(width, height) * (0.07 + mid * 0.06);
  let maxLinksPerParticle = 3;

  for (let i = 0; i < particles.length; i += 2) {
    let pA = particles[i];
    let links = 0;
    for (let j = i + 1; j < particles.length; j++) {
      let pB = particles[j];
      var dx = pB.x - pA.x;
      var dy = pB.y - pA.y;
      let dSq = dx * dx + dy * dy;
      if (dSq < linkThreshold * linkThreshold) {
        var dist = sqrt(dSq);
        let lineAlpha = map(dist, 0, linkThreshold, 140, 0) * (0.4 + mid * 0.6);
        let lineHue = (chord + pA.hueShift + 180) % 360;
        stroke(lineHue, 75, 85, lineAlpha);
        line(pA.x, pA.y, pB.x, pB.y);
        links++;
        if (links >= maxLinksPerParticle) break;
      }
    }
  }

  // Update and render each morphing particle
  for (let i = 0; i < particles.length; i++) {
    let p = particles[i];
    p.update(low, mid, high, beat, 0.016);
    p.render(low, mid, high, beat, chord);
  }
}

function mousePressed() {
  // Manual trigger for testing uniqueness metamorphosis
  initCosmosDNA();
}
